def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Coefficient part
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)

        # Variable part
        if degree == 1:
            var_str = 'x'
        elif degree > 1:
            var_str = f'x^{degree}'
        else:
            var_str = ''

        terms.append(sign + coeff_str + var_str)

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    :param encoded: A string representing the encoded information.
    :param original: A string representing the original information corresponding to the encoded string.
    :param message: A string representing the encrypted message to be decoded.
    :return: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != 26:
        return "Failed"

    try:
        decoded = "".join(mapping[c] for c in message)
    except KeyError:
        return "Failed"

    return decoded

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    Args:
        x0 (int): The required greatest common divisor of the pair.
        y0 (int): The required least common multiple of the pair.

    Returns:
        int: The number of ordered pairs (P, Q) satisfying the conditions.
    """
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n ** 0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""
    index_map = {ch: i for i, ch in enumerate(inorder)}

    def build(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end or post_start > post_end:
            return ""
        root = postorder[post_end]
        root_idx = index_map[root]
        left_size = root_idx - in_start
        left_pre = build(in_start, root_idx - 1, post_start, post_start + left_size - 1)
        right_pre = build(root_idx + 1, in_end, post_start + left_size, post_end - 1)
        return root + left_pre + right_pre

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

