def find_min_n_greater_than_k(k: int) -> int:
    """Return the smallest integer n such that the harmonic series sum
    S_n = 1 + 1/2 + ... + 1/n exceeds the given positive integer k."""
    n = 1
    harmonic_sum = 0.0
    while True:
        harmonic_sum += 1.0 / n
        if harmonic_sum > k:
            return n
        n += 1

def generate_numbers(n, rules):
    visited = set([n])
    queue = [n]
    while queue:
        cur = queue.pop(0)
        cur_str = str(cur)
        for i, ch in enumerate(cur_str):
            for x, y in rules:
                if ch == str(x):
                    new_num = int(cur_str[:i] + str(y) + cur_str[i+1:])
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Convert scenario and names to consistent case for comparison
    scenario_lower = scenario.lower()
    # Prepare lowercase set of days for easy check
    days_lower = {day.lower() for day in days_of_week}
    # Names list for pattern matching
    names = list(statements.keys())
    names_lower = {n.lower(): n for n in names}

    for speaker, stmts in statements.items():
        speaker_lower = speaker.lower()
        # Skip speakers with no statements
        if not stmts:
            continue
        for stmt in stmts:
            stmt_lower = stmt.lower()
            # Ignore if statement contains any day of week
            if any(day in stmt_lower for day in days_lower):
                continue

            truth = None
            # Self-statement patterns
            if "i am guilty" in stmt_lower:
                truth = (speaker_lower == scenario_lower)
            elif "i am not guilty" in stmt_lower:
                truth = (speaker_lower != scenario_lower)
            else:
                # Check statements about others
                for n_lower, orig_name in names_lower.items():
                    if f"{n_lower} is guilty" in stmt_lower:
                        truth = (orig_name.lower() == scenario_lower)
                        break
                    if f"{n_lower} is not guilty" in stmt_lower:
                        truth = (orig_name.lower() != scenario_lower)
                        break

            # If the statement could not be interpreted, skip it
            if truth is None:
                continue

            # Determine if speaker is expected to lie or tell the truth
            if speaker in liar_count:
                # Speaker is a liar, statement should be false
                if truth:
                    return False
            else:
                # Speaker is honest, statement should be true
                if not truth:
                    return False

    return True

