def min_remaining_space(V: int, n: int, volumes: list[int]) -> int:
    # DP array to track reachable volumes up to capacity V
    reachable = [False] * (V + 1)
    reachable[0] = True

    # Process each item
    for vol in volumes:
        if vol > V:
            # Skip items that individually exceed the capacity
            continue
        # Update reachable volumes in reverse to avoid reuse of the same item
        for cur in range(V, vol - 1, -1):
            if reachable[cur - vol]:
                reachable[cur] = True

    # Find the maximum occupied volume that does not exceed V
    max_occupied = 0
    for cur in range(V, -1, -1):
        if reachable[cur]:
            max_occupied = cur
            break

    # Minimum remaining space is capacity minus the maximum occupied volume
    return V - max_occupied

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    # Find maximum length of bitonic subsequence
    max_len = 0
    for i in range(n):
        cur = lis[i] + lds[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
